contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry point for the property test
    function run(uint256[] calldata winners) public payable {
        // precondition: winners length must match current winnersPerPeriod
        uint256 wp = c.winnersPerPeriod();
        require(winners.length == wp, "mismatch winnersPerPeriod");

        // observe before-values
        uint256 roundBefore = c.roundId();
        uint256 totalBefore = c.totalPoints();

        // read fighter points for each winner before the call
        uint256 sumPoints = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            // C exposes fighterPoints mapping as public getter
            uint256 p = c.fighterPoints(winners[i]);
            sumPoints += p;
        }

        // perform the state-changing call: pickWinner
        // it may revert if caller not admin; ensure this contract is admin by trying to call and capture revert
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After successful pickWinner, the contract should have set isSelectionComplete for the previous round (roundBefore)
        // and reset fighterPoints for the chosen winners to zero and decreased totalPoints by the sum of prior points.
        // If pickWinner reverted, we cannot assume any changes — so the property only applies when it didn't revert.

        if (!reverted) {
            // isSelectionComplete for roundBefore must be true
            bool done = c.isSelectionComplete(roundBefore);

            // totalPoints must have decreased by exactly sumPoints (or be at most totalBefore if underflow prevented)
            uint256 totalAfter = c.totalPoints();

            // compute fighterPoints after
            uint256 sumAfter = 0;
            for (uint256 i = 0; i < winners.length; i++) {
                uint256 p2 = c.fighterPoints(winners[i]);
                sumAfter += p2;
            }

            // Assert the general rule: selection marked complete and picked fighters' points cleared and totalPoints reduced accordingly
            assert(
                done && // selection completed
                sumAfter == 0 && // all picked winners now have zero points
                totalBefore == totalAfter + sumPoints // totalBefore - sumPoints == totalAfter
            );
        } else {
            // If it reverted, no general rule can be asserted about state change; but we still must reach a single assert.
            // In the revert case, assert that nothing impossible is claimed: roundId hasn't changed or isSelectionComplete for previous round is false.
            // Read values
            uint256 roundAfter = c.roundId();
            bool maybeDone = c.isSelectionComplete(roundBefore);
            // If reverted, either roundId unchanged or selection not marked complete for that round
            assert(roundAfter == roundBefore || maybeDone == false);
        }
    }

    receive() external payable {}
}

