        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values (always allowed)
        uint256 roundAfter = c.roundId();
        bool selectionDone = c.isSelectionComplete(roundBefore);
        uint256 totalAfter = c.totalPoints();

        // compute sum of fighterPoints after
        uint256 sumAfter = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            uint256 p2 = c.fighterPoints(winners[i]);
            sumAfter += p2;
        }

        // Single assert encoding both cases:
