        // We assert: if pickWinner succeeded then selectionDone is true, sumAfter == 0, and totalBefore == totalAfter + sumPoints.
        // If pickWinner reverted then we assert that roundId did not advance (roundAfter == roundBefore).
        assert(
            (!reverted && selectionDone && sumAfter == 0 && totalBefore == totalAfter + sumPoints)
            || (reverted && roundAfter == roundBefore)
        );
    }

    receive() external payable {}
