contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // winners: array of tokenIds to pass to pickWinner
    function run(uint256[] calldata winners) public payable {
        require(winners.length > 0);
        // fetch current winnersPerPeriod and roundId
        uint256 wp = c.winnersPerPeriod();
        uint256 rid = c.roundId();
        // precondition: caller (this contract) must be admin in c to call pickWinner
        // We cannot call transferOwnership on c (only owner can), but the constructor of c makes deployer an admin.
        // The test deployer is different; however checker deploys c fresh and passes it to this test's constructor,
        // so this contract is NOT necessarily admin. To satisfy calling pickWinner, we first adjust admin (if possible).
        // We attempt to call adjustAdminAccess; it will revert unless msg.sender is owner. So instead we require winners.length == wp
        require(winners.length == wp, "must match winnersPerPeriod");

        // Read totalPoints and fighterPoints before
        uint256 totalBefore = c.totalPoints();
        uint256 sumPoints = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            uint256 tid = winners[i];
            // fighterPoints is public mapping -> getter
            uint256 p = c.fighterPoints(tid);
            sumPoints += p;
        }

        bool reverted;
        // Try calling pickWinner; catch revert
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observations after call
        uint256 totalAfter = c.totalPoints();
        bool selectionComplete = c.isSelectionComplete(rid);

        // If call reverted then state must be unchanged: totalPoints should be equal and isSelectionComplete false
        // If call succeeded then totalAfter == totalBefore - sumPoints and for each winner fighterPoints==0 and isSelectionComplete true
        bool postCondition;
        if (reverted) {
            postCondition = (totalAfter == totalBefore) && (selectionComplete == false);
        } else {
            // check fighterPoints zeroed
            bool zeroed = true;
            for (uint256 i = 0; i < winners.length; i++) {
                if (c.fighterPoints(winners[i]) != 0) { zeroed = false; break; }
            }
            postCondition = (totalAfter + sumPoints == totalBefore) && zeroed && selectionComplete == true;
        }

        assert(postCondition);
    }
    receive() external payable {}
}

