contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // winners: array of tokenIds to pass to pickWinner
    // callerMustBeAdmin flag: when true we assume msg.sender (this contract) has been made admin off-chain by constructor of C; if not, pickWinner will revert and the invariant should not be required in that case.
    function run(uint256[] calldata winners) public payable {
        require(winners.length > 0, "need at least one winner id");
        // read initial roundId
        uint256 beforeRoundId = c.roundId();
        // read before values of fighterPoints and totalPoints
        uint256 beforeTotalPoints = c.totalPoints();
        uint256 len = winners.length;
        // sum fighterPoints for provided winners using public getter
        uint256 sumPoints = 0;
        for (uint256 i = 0; i < len; i++) {
            uint256 pid = winners[i];
            // c.fighterPoints(pid) is public mapping getter
            uint256 fp = c.fighterPoints(pid);
            sumPoints += fp;
        }

        // try to call pickWinner and detect revert
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After call: either it reverted (no state change) or it succeeded.
        // If reverted, roundId and totalPoints must be unchanged and isSelectionComplete for beforeRoundId must be false.
        // If succeeded, roundId must have incremented by 1, totalPoints must have decreased by sumPoints,
        // fighterPoints for each winner must be zero, and isSelectionComplete for beforeRoundId must be true.
        uint256 afterRoundId = c.roundId();
        uint256 afterTotalPoints = c.totalPoints();

        if (reverted) {
            assert(afterRoundId == beforeRoundId && afterTotalPoints == beforeTotalPoints && c.isSelectionComplete(beforeRoundId) == false);
        } else {
            // successful pickWinner: exactly one round advanced
            assert(afterRoundId == beforeRoundId + 1);
            assert(afterTotalPoints + sumPoints == beforeTotalPoints);
            // each selected winner's points must be zero now
            for (uint256 i = 0; i < len; i++) {
                uint256 pid = winners[i];
                assert(c.fighterPoints(pid) == 0);
            }
            // the selection for the handled round (beforeRoundId) must be marked complete
            assert(c.isSelectionComplete(beforeRoundId) == true);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // winners must match winnersPerPeriod to avoid obvious revert from wrong length
    function run(uint256[] calldata winners) public payable {
        require(winners.length > 0, "need at least one winner id");
        // observe before state
        uint256 beforeRoundId = c.roundId();
        uint256 beforeTotalPoints = c.totalPoints();
        uint256 winnersLength = winners.length;
        // sum fighterPoints for provided winners via public getter
        uint256 sumPoints = 0;
        for (uint256 i = 0; i < winnersLength; i++) {
            uint256 pid = winners[i];
            uint256 fp = c.fighterPoints(pid);
            sumPoints += fp;
        }

        // attempt pickWinner as a top-level state-changing call and capture revert via try/catch
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after state
        uint256 afterRoundId = c.roundId();
        uint256 afterTotalPoints = c.totalPoints();

        // Single general assert expressing the bifurcation: if reverted then no changes, else the effects hold
        assert(
            (reverted && afterRoundId == beforeRoundId && afterTotalPoints == beforeTotalPoints && c.isSelectionComplete(beforeRoundId) == false)
            ||
            (!reverted
                && afterRoundId == beforeRoundId + 1
                && beforeTotalPoints == afterTotalPoints + sumPoints
                && c.isSelectionComplete(beforeRoundId) == true
                && _allZeroed(winners))
        );
    }

    // helper view function (allowed) to check all selected fighterPoints are zero using public getter
    function _allZeroed(uint256[] calldata winners) internal view returns (bool) {
        for (uint256 i = 0; i < winners.length; i++) {
            if (c.fighterPoints(winners[i]) != 0) return false;
        }
        return true;
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // require at least one winner and limit winners length to a reasonable bound to allow looping
    function run(uint256[] calldata winners) public payable {
        require(winners.length > 0, "need at least one winner");
        // Observe before-values via public getters
        uint256 beforeRoundId = c.roundId();
        uint256 beforeTotalPoints = c.totalPoints();
        // compute sum of fighterPoints for provided winner ids
        uint256 sumPoints = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            uint256 id = winners[i];
            // read public mapping getter
            uint256 fp = c.fighterPoints(id);
            sumPoints += fp;
        }

        // Attempt pickWinner as a top-level call and capture whether it reverted
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-values
        uint256 afterRoundId = c.roundId();
        uint256 afterTotalPoints = c.totalPoints();
        bool selectionCompleteBefore; // whether the prior round (beforeRoundId) is marked complete AFTER the call
        // if beforeRoundId is unchanged (i.e., pickWinner reverted), check isSelectionComplete(beforeRoundId) remains as it was before by reading it now
        // If not reverted, pickWinner should have set isSelectionComplete for the previous round (the one indexed by beforeRoundId) to true
        selectionCompleteBefore = c.isSelectionComplete(beforeRoundId);

        // Single assertion: either reverted and nothing changed (roundId and totalPoints unchanged and selectionComplete stayed as observed),
        // or not reverted and effects hold: roundId increased by 1, selectionComplete for previous round is true, and totalPoints decreased by at least sumPoints
        assert(
            (reverted
                && afterRoundId == beforeRoundId
                && afterTotalPoints == beforeTotalPoints
                && selectionCompleteBefore == c.isSelectionComplete(beforeRoundId)
            )
            ||
            (!reverted
                && afterRoundId == beforeRoundId + 1
                && c.isSelectionComplete(beforeRoundId) == true
                && beforeTotalPoints >= afterTotalPoints
                && (beforeTotalPoints - afterTotalPoints) >= sumPoints
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // require at least one winner and a reasonable upper bound to ensure loops terminate
    function run(uint256[] calldata winners) public payable {
        require(winners.length > 0 && winners.length <= 10, "invalid winners length");

        // Observe before-values via public getters
        uint256 beforeRoundId = c.roundId();
        uint256 beforeTotalPoints = c.totalPoints();

        // compute sum of fighterPoints for provided winner ids (using public mapping getter)
        uint256 sumPoints = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            uint256 id = winners[i];
            uint256 fp = c.fighterPoints(id);
            sumPoints += fp;
        }

        // Attempt pickWinner as a top-level call and capture whether it reverted
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-values
        uint256 afterRoundId = c.roundId();
        uint256 afterTotalPoints = c.totalPoints();

        // Single assertion: either reverted and no observable change in roundId and totalPoints,
        // or not reverted and effects hold: roundId increased by 1, selectionComplete for previous round is true,
        // and totalPoints decreased by at least sumPoints (since fighterPoints for winners should be zeroed)
        assert(
            (reverted
                && afterRoundId == beforeRoundId
                && afterTotalPoints == beforeTotalPoints
            )
