        // Instead, rely on the freshly deployed C having its deployer (the harness) as admin; the checker deploys C and then deploys this test with that C, so this contract is NOT owner. To satisfy pickWinner's onlyRole requirement, we will avoid requiring admin and instead use the approach: call addPoints via the known rankedBattleAddress is required; but we can still call pickWinner only if isAdmin[msg.sender] true. msg.sender will be this test contract. The only way to be admin is if the initial owner equals this contract; that's not guaranteed.
        // To make the test work across deployments, we will not CALL pickWinner if pick would revert; we'll attempt the call and check the invariant conditional on it not reverting.

        // Sample observations before the call
        uint256 roundBefore = c.roundId();
        uint256 totalBefore = c.totalPoints();
        // read fighterPoints for ids provided (via getFighterPoints requires a maxId param). We use maxId = winners.length (safe) and then copy relevant entries
        uint256[] memory ptsArray = c.getFighterPoints(winners.length);
        // compute sum of points of the winners indices (only if index < ptsArray.length)
        uint256 sumPts = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            uint256 id = winners[i];
            if (id < ptsArray.length) {
                sumPts += ptsArray[id];
            } else {
                // id out of observed range: we cannot know its points; to keep property meaningful, treat its contribution as 0
            }
        }

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observations after
        uint256 roundAfter = c.roundId();
        uint256 totalAfter = c.totalPoints();

        // Rule: If pickWinner did not revert, then the roundId should have incremented by 1,
        // isSelectionComplete for the previous round should be true, and totalPoints decreased by at least the sum of fighterPoints we observed for the provided ids (since we may have missed points of ids beyond observed range).
        // Also, for any winner index that was in observed range, fighterPoints for that id must be zero after the call.
        bool allCleared = true;
        if (!reverted) {
            for (uint256 i = 0; i < winners.length; i++) {
                uint256 id = winners[i];
                if (id < ptsArray.length) {
                    // read fighterPoints[id] by calling getFighterPoints again and checking
                    uint256[] memory afterPts = c.getFighterPoints(winners.length);
                    if (afterPts[id] != 0) {
                        allCleared = false;
