                    }
                }
            }
        }

        if (reverted) {
            // if reverted, we cannot assume state changed; assert a relation that allows either outcome
            assert(reverted == true);
        } else {
            // general rule asserted
            assert(
                roundAfter == roundBefore + 1
                && c.isSelectionComplete(roundBefore)
                && totalBefore >= totalAfter
                && totalBefore - totalAfter >= sumPts
                && allCleared
            );
        }
    }

