            reverted = false;
        } catch {
            reverted = true;
        }

        // After-call observations
        uint256 afterTotal = c.totalPoints();
        // sum of cleared points from beforePoints for winners that existed
        uint256 sumCleared = 0;
        for (uint256 i = 0; i < wp; i++) {
            // read current fighterPoints
            uint256 fp = c.fighterPoints(winners[i]);
            // If the call succeeded, rule requires fighterPoints for those ids are zero.
            // If reverted, state must be unchanged for these points (we check equality below).
            // accumulate beforePoints to compare with total delta
            sumCleared += beforePoints[i];
        }

        // The general rule to assert:
        // If pickWinner did NOT revert then:
        //  - each chosen winner's fighterPoints must be zero now
        //  - afterTotal must equal beforeTotal minus sum of the previous fighterPoints
        //  - isSelectionComplete for the previous round (roundId - 1) must be true
        // If pickWinner reverted then nothing is required except that we don't assert state changes.

