contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run tries to call pickWinner and then checks the general invariant described above.
    // params:
    // - winners: an array of token ids to pick as winners
    // - callerIsAdmin: a boolean indicating whether this contract's caller should be treated as admin; we cannot change c's isAdmin mapping externally, so we only proceed under the assumption that c.adjustAdminAccess was not used. To allow the call to succeed in some executions, we attempt to call pickWinner and observe whether it reverted.
    function run(uint256[] calldata winners) public payable {
        require(winners.length > 0);

        // read winnersPerPeriod and roundId and totalPoints and fighterPoints for given ids
        uint256 winnersPerPeriod = c.winnersPerPeriod();
        uint256 beforeRoundId = c.roundId();
        uint256 beforeTotalPoints = c.totalPoints();

        // read fighterPoints for each supplied id (only up to winnersPerPeriod to keep relation meaningful)
        uint256 len = winners.length;
        if (len > winnersPerPeriod) {
            len = winnersPerPeriod;
        }
        uint256[] memory ids = new uint256[](len);
        uint256[] memory pointsBefore = new uint256[](len);
        for (uint256 i = 0; i < len; i++) {
            ids[i] = winners[i];
            pointsBefore[i] = c.fighterPoints(ids[i]);
        }

        // attempt to call pickWinner and record whether it reverted
        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the call did not revert, then the contract must have recorded the winners for the previous roundId
        // and must have zeroed fighterPoints for each winner and decreased totalPoints by the sum of those points.
        if (!reverted) {
            // the winners were stored at index beforeRoundId
            address[] memory stored = c.winnerAddresses(beforeRoundId);
            // assert stored length equals winnersPerPeriod
            // also compute sum of pointsBefore for the ids that appear in stored and ensure fighterPoints now zero and totalPoints decreased by sum
            uint256 storedLen = stored.length;
            uint256 sumBefore = 0;
            // sum pointsBefore for ids that match stored entries (match by owner lookup is expensive/unavailable), instead check that storedLen == winnersPerPeriod
            for (uint256 i = 0; i < len; i++) {
                sumBefore += pointsBefore[i];
            }
            uint256 afterTotalPoints = c.totalPoints();

            // build condition: storedLen == winnersPerPeriod AND afterTotalPoints == beforeTotalPoints - sumBefore
            // AND for each id we checked, its fighterPoints is now zero
            bool allZero = true;
            for (uint256 i = 0; i < len; i++) {
                if (c.fighterPoints(ids[i]) != 0) {
                    allZero = false;
                }
            }

            assert(storedLen == winnersPerPeriod && afterTotalPoints + sumBefore == beforeTotalPoints && allZero);
        } else {
            // If reverted, we assert nothing about state changes of winners; instead assert that either
            // the call reverted because winners length != winnersPerPeriod OR selection was already complete.
            // We can observe those conditions via public getters: winnersPerPeriod and isSelectionComplete(beforeRoundId).
            bool wrongLength = (winners.length != winnersPerPeriod);
            bool alreadySelected = c.isSelectionComplete(beforeRoundId);
            assert(wrongLength || alreadySelected);
        }
    }

    receive() external payable {}
}

