            bool totalDecreased = afterTotal + sumOld == beforeTotalPoints;
            // check round advanced
            bool roundAdvanced = afterRound == beforeRound + 1;
            // check each picked fighterPoints is zero and winnerAddresses recorded owner matches ownerOf
            bool allZero = true;
            for (uint256 i = 0; i < len; i++) {
                if (c.fighterPoints(toPick[i]) != 0) { allZero = false; break; }
            }
            bool selectionFlag = c.isSelectionComplete(beforeRound);
            assert(totalDecreased && roundAdvanced && allZero && selectionFlag);
        } else {
            // If pickWinner reverted, then it must be because either caller not admin or incorrect number of winners or selection already complete.
            // We assert that at least one of these observable conditions holds: not isAdmin(msg.sender) is not readable, but we can observe winnersPerPeriod mismatch or isSelectionComplete true.
            // We require that when reverted, either winners.length != winnersPerPeriod OR isSelectionComplete[roundId] == true.
            // We can check the latter for the current beforeRound.
            bool alreadySelected = c.isSelectionComplete(beforeRound);
            // winners length mismatch is captured by comparing len to wp (they are equal by construction), so the only observable reason must be alreadySelected.
            assert(alreadySelected);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // winners array provided as input; length must match current winnersPerPeriod to avoid trivial revert
    function run(uint256[] calldata winners) public payable {
        require(winners.length > 0);

        uint256 wp = c.winnersPerPeriod();
        require(wp > 0);
        // require input length equals winnersPerPeriod so pickWinner is not invalid for that reason
        require(winners.length == wp);

        uint256 beforeRound = c.roundId();
        uint256 beforeTotal = c.totalPoints();

        // snapshot old points for each provided winner id
        uint256[] memory oldPoints = new uint256[](wp);
        uint256 sumOld = 0;
        for (uint256 i = 0; i < wp; i++) {
            oldPoints[i] = c.fighterPoints(winners[i]);
            sumOld += oldPoints[i];
        }

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: if call succeeded then roundId increased by 1, previous round marked complete, each picked fighterPoints is zero, and totalPoints decreased by sumOld
        assert(reverted || (
            c.roundId() == beforeRound + 1 &&
            c.isSelectionComplete(beforeRound) &&
            c.totalPoints() + sumOld == beforeTotal &&
            // all cleared to zero
            (function() internal view returns (bool) {
                for (uint256 i = 0; i < wp; i++) {
                    if (c.fighterPoints(winners[i]) != 0) return false;
                }
                return true;
            })()
        ));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Provide exactly winnersPerPeriod ids to pick as winners
    function run(uint256[] calldata winners) public payable {
        // read winnersPerPeriod and require input length matches to avoid trivial revert
        uint256 wp = c.winnersPerPeriod();
        require(wp > 0, "winnersPerPeriod must be > 0");
        require(winners.length == wp, "input length must equal winnersPerPeriod");

        // snapshot state before the call
        uint256 beforeRound = c.roundId();
        uint256 beforeTotal = c.totalPoints();

        // record old points for each winner id and sum them
        uint256 sumOld = 0;
        for (uint256 i = 0; i < wp; i++) {
            uint256 pid = winners[i];
            uint256 pts = c.fighterPoints(pid);
            sumOld += pts;
        }

        bool reverted;
        // call pickWinner and catch revert
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If the call did not revert, assert the invariant described in the summary.
        // We must express that for successful call: roundId == beforeRound+1,
        // isSelectionComplete(beforeRound) == true,
        // totalPoints == beforeTotal - sumOld,
        // and for all provided winners, fighterPoints(id) == 0.
        // Build the conjunction manually.
        if (!reverted) {
            // check round increment and selection flag and totalPoints change
            bool cond1 = (c.roundId() == beforeRound + 1);
            bool cond2 = c.isSelectionComplete(beforeRound);
            bool cond3 = (c.totalPoints() + sumOld == beforeTotal);
            // check all fighterPoints cleared
            bool allCleared = true;
            for (uint256 i = 0; i < wp; i++) {
                if (c.fighterPoints(winners[i]) != 0) {
                    allCleared = false;
                    break;
                }
            }
            assert(cond1 && cond2 && cond3 && allCleared);
        } else {
            // if reverted, we allow any behavior — but we still must reach a single assert;
            // assert that the call indeed reverted (i.e., reverted == true) by asserting reverted is true
            // This keeps the single assert requirement satisfied in both branches overall because
            // the function must end with exactly one assert; to satisfy the problem statement we
            // place an assert here that is implied by the flow: in reverted case, assert(reverted).
            assert(reverted);
        }
    }

    receive() external payable {}
}
